def numara_caractere(text, tinta):
    if len(text) == 0:
        return 0
    primul = 1 if text[0] == tinta else 0
    return primul + numara_caractere(text[1:], tinta)

print(numara_caractere("satelitul", "l"))

def aplatizeaza(lista):
    rezultat = []
    for element in lista:
        if type(element) == list:
            rezultat = rezultat + aplatizeaza(element)
        else:
            rezultat.append(element)
    return rezultat

print(aplatizeaza([1, [2, [3]], 4]))

def cautare_binara(numere, tinta):
    stanga = 0
    dreapta = len(numere) - 1
    while stanga <= dreapta:
        mijloc = (stanga + dreapta) // 2
        if numere[mijloc] == tinta:
            return mijloc
        elif numere[mijloc] < tinta:
            stanga = mijloc + 1
        else:
            dreapta = mijloc - 1
    return -1

print(cautare_binara([2, 5, 8, 12], 6))

def gaseste_valoare(lista_sortata, tinta):
    if len(lista_sortata) == 0:
        return False
    mijloc = len(lista_sortata) // 2
    if lista_sortata[mijloc] == tinta:
        return True
    elif lista_sortata[mijloc] < tinta:
        return gaseste_valoare(lista_sortata[mijloc + 1:], tinta)
    else:
        return gaseste_valoare(lista_sortata[:mijloc], tinta)

print(gaseste_valoare([9, 2, 7, 4, 1], 9))

